/**
 * Microsoft Teams Node - Version 2
 * Discriminator: resource=chatMember, operation=add
 */


interface Credentials {
  microsoftTeamsOAuth2Api: CredentialReference;
  microsoftOAuth2Api: CredentialReference;
  microsoftEntraServicePrincipalApi: CredentialReference;
}

/** Add a member to a chat */
export type MicrosoftTeamsV2ChatMemberAddParams = {
  resource: 'chatMember';
  operation: 'add';
  authentication?: 'microsoftTeamsOAuth2Api' | 'microsoftOAuth2Api' | 'microsoftEntraServicePrincipalApi';
/**
 * Select the group chat from the list, or specify its ID (find the chat ID after "conversations/" in the URL). One-on-one chats are not listed because Teams does not allow adding members to a 1:1 chat.
 * @searchListMethod getChats
 * @displayOptions.hide { /authentication: ["microsoftEntraServicePrincipalApi"] }
 * @default {"mode":"list","value":""}
 */
    chatId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Select the user from the list or by ID. Guest users must be given by their object ID, not by their user principal name.
 * @searchListMethod getUsers
 * @displayOptions.hide { /authentication: ["microsoftEntraServicePrincipalApi"] }
 * @default {"mode":"list","value":""}
 */
    userId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Other options to set
 * @displayOptions.hide { /authentication: ["microsoftEntraServicePrincipalApi"] }
 * @default {}
 */
    options?: {
    /** Point in time from which the chat history is shared
     * @displayOptions.show { shareHistory: ["fromDate"] }
     */
    historyStartDate?: string | Expression<string>;
    /** Select Guest for a B2B guest user, since adding a guest as an owner fails. A guest must be identified by object ID, not by user principal name.
     * @default owner
     */
    role?: 'guest' | 'owner' | Expression<string>;
    /** How much of the existing chat history the new member can read
     * @default none
     */
    shareHistory?: 'all' | 'fromDate' | 'none' | Expression<string>;
  };
};

export type MicrosoftTeamsV2ChatMemberAddOutput = {
  success?: boolean;
};

export type MicrosoftTeamsV2ChatMemberAddNode = {
  type: 'n8n-nodes-base.microsoftTeams';
  version: 2;
  config: NodeConfig<MicrosoftTeamsV2ChatMemberAddParams> & { credentials?: Credentials };
  output?: Items<MicrosoftTeamsV2ChatMemberAddOutput>;
};